<?php 
    $profiles=$db->query('SELECT p.*, (SELECT COUNT(*) FROM articles a WHERE a.author_profile_id=p.id) AS total FROM author_profiles p ORDER BY name')->fetchAll();
    $editId=(int)($_GET['id']??0);$editing=null;
    foreach($profiles as $prof)if((int)$prof['id']===$editId)$editing=$prof; ?>
    <div class="panel"><div class="panel-heading"><h2>Assinaturas editoriais</h2><span class="muted tiny">Diferentes das contas de acesso</span></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Notícias</th><th>Ações</th></tr></thead><tbody><?php foreach($profiles as $prof): ?><tr><td><strong><?= h($prof['name']) ?></strong><small class="caption-hint"><?= h($prof['bio']) ?></small></td><td><?= (int)$prof['total'] ?></td><td class="action-cell"><a href="<?= h(admin_link('authors')) ?>&id=<?= (int)$prof['id'] ?>#edit-author">Editar</a><form method="post" action="<?= h(admin_link('delete_author')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$prof['id'] ?>"><button class="danger-link" data-confirm="Remover perfil do autor? Matérias serão mantidas.">Remover</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
    <div class="panel form-panel" id="edit-author"><h2><?= $editing?'Editar autor':'Novo autor' ?></h2><form method="post" action="<?= h(admin_link('save_author')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><div class="form-grid"><label>Nome público<input name="name" maxlength="120" required value="<?= h($editing['name']??'') ?>"></label><label class="full">Biografia curta<textarea name="bio" maxlength="500" rows="3"><?= h($editing['bio']??'') ?></textarea></label></div><button class="btn primary">Salvar autor</button></form></div>
